INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(23577, 1, 0, 'koKR', 'Nie wy... pokonać tej mocy!'),
(23577, 3, 0, 'koKR', 'Ja walczyć z nieokiełznanym duchem...'),
(23577, 5, 0, 'koKR', 'Chaga... chokajinn.'),
(23863, 0, 0, 'koKR', 'Wszyscy zawsze chcieć nam coś zabrać. Teraz my zacząć odbierać. Kto stanąć nam na drodze... utopić się we własnej krwi! Imperium Amanów wrócić... po zemstę. A zacząć my... od was!'),
(23863, 1, 0, 'koKR', 'Nikt nie być groźniejszy ode mnie!'),
(23863, 7, 0, 'koKR', 'Wy za wolni! Ja za silny!'),
(24144, 1, 0, 'koKR', 'Nie wy... pokonać tej mocy!'),
(24144, 3, 0, 'koKR', 'Ja walczyć z nieokiełznanym duchem...'),
(24144, 5, 0, 'koKR', 'Chaga... chokajinn.');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(22144, 'koKR', 'Ruszać się, strażnicy! Czas zabijania!', '', 0),
(22145, 'koKR', 'Mua-ha-ha!', '', 0),
(22146, 'koKR', 'Strażnicy, no już! Kogo bać się bardziej, ich... czy mnie?', '', 0),
(22151, 'koKR', 'Jazda! Ruszać tam i przynieść mi parę głów!', '', 0),
(22155, 'koKR', 'Ja tracić cierpliwość! No dalej: niech żałować, że się urodzili!', '', 0),
(22838, 'koKR', 'Ja pokazać wam siłę... w liczbie.', '', 0),
(22971, 'koKR', 'Akil\'zonie, najeźdźcy nadchodzą!', '', 0),
(23109, 'koKR', 'Najeźdźcy! Podnieść alarm!', 'Najeźdźcy! Podnieść alarm!', 0),
(23166, 'koKR', 'Wy już niedługo martwi!', '', 0),
(23167, 'koKR', 'Ja przynosić ból!', '', 0),
(23168, 'koKR', 'Wołać bestię, to dostać więcej, niż chcieć!', '', 0),
(23169, 'koKR', 'Z drogi dla Nalorakka!', '', 0),
(23170, 'koKR', 'Wy mieć swoją szansę, teraz za późno!', '', 0),
(23171, 'koKR', 'No i co teraz powiedzieć?', '', 0),
(23172, 'koKR', 'Amanowie znów rządzić!', '', 0),
(23173, 'koKR', 'Ja... czekać po drugiej stronie...', '', 0),
(23175, 'koKR', 'Ja mieć nowe sztuczki... jak mój brat niedźwiedź...', '', 0),
(23176, 'koKR', 'Przed orłem nie być ukrycia!', '', 0),
(23177, 'koKR', 'Poznajcie moich nowych braci: kieł i pazur!', '', 0),
(23178, 'koKR', 'Nie trzeba patrzeć w niebo, by zobaczyć smoczego jastrzębia!', '', 0),
(23179, 'koKR', 'Ogień zabić was tak samo szybko!', '', 0),
(23181, 'koKR', 'Da Amani di chuka!', '', 0),
(23182, 'koKR', 'Dużo więcej padnie jak wy.', '', 0),
(23183, 'koKR', 'Może ja paść... ale imperium Amanów... nigdy nie umrzeć.', '', 0),
(23232, 'koKR', 'Nie zabić... mojego... ducha!', '', 0),
(23233, 'koKR', 'Przestać płakać!', '', 0),
(23234, 'koKR', 'Wy nic nie mieć!', '', 0),
(23235, 'koKR', 'Ja być drapieżnik! Wy ofiara...', '', 0),
(23236, 'koKR', 'Wy tylko marnować mój czas!', '', 0),
(23238, 'koKR', 'Dzięki za troskę, ale zamierzamy zbadać Zul\'Aman.', 'Dzięki za troskę, ale zamierzamy zbadać Zul\'Aman.', 0),
(23252, 'koKR', 'Więcej intruzów! Podnieść alarm!', '', 0),
(23305, 'koKR', 'Co lepsze niż służyć duchowi niedźwiedzia przez wieczność? Podejdźcie bliżej. Oddajcie mi swoje dusze!', '', 0),
(23306, 'koKR', 'Ja was czuć, obcy. Nie zwlekać ze swoim losem. Chodźcie do mnie. Ja złożyć was w ofierze szybko.', '', 0),
(23308, 'koKR', 'Wasza śmierć być szybka, obcy. Nie trzeba było tu przychodzić...', '', 0),
(23313, 'koKR', 'Chodźcie, przyjaciele. Wasze ciała nakarmić moje pisklęta, a wasze dusze napełnić mnie mocą!', '', 0),
(23314, 'koKR', 'Chodźcie, obcy. Duch smoczego jastrzębia być głodny godnych dusz.', '', 0),
(23528, 'koKR', 'Gdzie moje wylęgacze? Brać się do roboty przy tych jajach!', '', 0),
(23585, 'koKR', 'Teraz już po wszystkim, mon!', '', 0),
(23586, 'koKR', 'Tazaga-choo!', '', 0),
(23587, 'koKR', 'Zul\'jin... mieć dla was niespodziankę...', '', 0),
(23588, 'koKR', 'Wam właśnie skończyć się czas!', '', 0),
(23589, 'koKR', 'Ja was teraz spalić!', '', 0),
(23590, 'koKR', 'Duchy wiatru być waszą zgubą!', '', 0),
(23636, 'koKR', 'Dobra rada, przybyszu: wracaj tam, skąd przychodzisz.$b$bTo nie miejsce dla beztroskich poszukiwaczy przygód. Takich jak ty przeżuwa i wypluwa same kości.', '', 0),
(23931, 'koKR', 'Jedzcie, bracia!', '', 0),
(24263, 'koKR', '%s zamienia się w niedźwiedzia!', '', 0),
(24294, 'koKR', 'Jak sobie chcecie. Żeby dostać się do środka, musi mi pomóc co najmniej troje z was. Za mną...', '', 0),
(24295, 'koKR', 'Według moich obliczeń, jeśli dość wielu z nas uderzy w gong jednocześnie, pieczęć na tych drzwiach pęknie i będziemy mogli wejść.', '', 0);
